// commit_mode — 三态校验 + 合并写入 save/playthrough/mode.json。
// input: { mode: Record<string, "enabled"|"disabled"|"deferred"> }。读取现有 mode.json 合并传入键（不覆盖未传入的键）。
const COMMIT_MODE_SCRIPT_JS = `${text([
  "async function commitMode(input, tsian, signal) {",
  "  try {",
  "    signal.throwIfAborted();",
  "    if (!isRecord(input)) fail('OPENING_COMMIT_INVALID', 'Commit input must be an object.');",
  "    if (!isRecord(input.mode)) fail('OPENING_MODE_INVALID', 'mode must be an object.');",
  "    const ALLOWED_STATES = ['enabled', 'disabled', 'deferred'];",
  "    const incoming = {};",
  "    for (const [key, value] of Object.entries(input.mode)) {",
  "      if (typeof key !== 'string' || !key.trim()) fail('OPENING_MODE_KEY_INVALID', 'mode key must be a non-empty string.', { key });",
  "      if (typeof value !== 'string' || !ALLOWED_STATES.includes(value)) fail('OPENING_MODE_VALUE_INVALID', 'mode value must be one of enabled/disabled/deferred.', { key, value });",
  "      incoming[key.trim()] = value;",
  "    }",
  "    let existing = {};",
  "    try { const file = await tsian.workspace.read({ scope: 'effective', path: 'save/playthrough/mode.json' }); if (file && typeof file.content === 'string') existing = JSON.parse(file.content); } catch (error) { existing = {}; }",
  "    if (!isRecord(existing)) existing = {};",
  "    const merged = { ...existing, ...incoming };",
  "    const file = await tsian.workspace.write({ scope: 'save-runtime', path: 'save/playthrough/mode.json', content: JSON.stringify(merged, null, 2) + '\\n', mediaType: 'application/json' });",
  "    tsian.trace('mode_committed', { keys: Object.keys(incoming), write: file.path });",
  "    return { status: 'ready', write: { path: file.path, size: file.content.length } };",
  "  } catch (error) {",
  "    tsian.trace('mode_commit_failed', { code: error && error.code || 'OPENING_COMMIT_FAILED', message: error && error.message || String(error), details: error && error.details });",
  "    throw error;",
  "  }",
  "}",
  "return commitMode(input, tsian, signal);",
])}`

