  "    \"inputSchema\": { \"type\": \"object\", \"required\": [\"mode\"], \"properties\": { \"mode\": { \"type\": \"object\", \"additionalProperties\": { \"type\": \"string\", \"enum\": [\"enabled\", \"disabled\", \"deferred\"] } } } },",
